              "current": "    if (!jailed) Promise.all([api('GET', '/v1/onboard'), api('GET', '/v1/paper')]).then(([o, p]) => {\n      if (navigationRevision === landingRevision && ((o.body && !o.body.allDone) || (p.body && p.body.fresh))) setTab('start');\n    }).catch(() => { /* the current screen remains usable if optional landing data is unavailable */ });\n  }\n  // one renderer per tab (deck/city/den built once at boot; the rest re-render on entry). Function\n  // declarations are hoisted, so this map can name them here.\n  const RENDERERS = { start: renderStart, profile: renderProfile, streets: renderStreets, city: renderCity, den: renderDen,\n    kitchen: renderKitchen, family: renderFamily, market: renderMarket, pvp: renderPvp, law: renderLaw,\n    garage: renderGarage, empire: renderEmpire, business: renderBusiness, speakeasy: renderSpeakeasy, boxing: renderBoxing,\n    scores: renderScores, loans: renderLoans, portfolio: renderPortfolio, estate: renderEstate,\n    life: renderLife, pen: renderPen, wire: renderWire, store: renderStore, races: renderRaces, port: renderPort, stable: renderStable,\n    crew: renderCrew, discover: renderDiscover, map: renderMap, deeds: renderDeeds, desk: renderContentDesk, world: renderWorld, fieldwork: renderFieldwork };\n  // ── FIRST-VISIT SYSTEM INTROS — the tutorial, scaled across the whole city: the first time a\n  // player opens a system they get ONE illustrated sentence on what it is and what to do first.\n  // Dismiss is remembered per tab. Prose is English like all game prose (the i18n chrome rule).\n  const TAB_INTRO = {\n    discover: 'Find people to run with: players near your level, who’s looking for a crew, and the newest faces in the city. Flag yourself “looking for a crew” and let someone find YOU. This is the front door — the Wet Work roster only shows the top of the heap.',\n    crew: 'Your crew: a 2–' + 4 + ' player pact between solo and a full family. No treasury, no turf — just a private room, each other’s backs, and a rule you don’t raise a hand to your own. Form one, or accept an invite.',\n    map: 'See who holds the city: family territory, contested ground, and occupied districts. Fight for turf from The Family tab, or visit City events to travel to another district.',\n    city: 'The living city: today\\'s events, the weather that moves goods prices (the arbitrage map), rival NPC cartels to raid, and the monument the whole server is building. Check the forecast — plan around it.',\n    kitchen: 'The drug game: buy makings, cook a batch, deal it on the corner. Deals draw heat, heat draws the Law — lay low when it climbs. Hire crew and they sell for you while you sleep.',\n    empire: 'Legit fronts that farm cash while you\\'re away. They cost upkeep, rivals can shake them down — and if you\\'re killed, your killer can take one. Passive is not the same as safe.',\n    business: 'Run your company with real inventory, production, deliveries and customer sales. Cash flow records game-cash movements, including refundable escrow and transfers; it is not a profit forecast.',\n    scores: 'The big jobs: your solo Score, crew heists (crew up with real players — or rat), and smuggling convoys anyone on the road can ambush. Start with the solo Score, crew up at level 8.',\n    market: 'Player-to-player trade: auction cars, buy and sell goods (pickup is district-pinned — you go to the dock), post buy orders. Prices are set by people, so the deals are real.',\n    port: 'Contraband by sea: buy a boat, run a route, slip the Coast Guard. Faster boats and escorts beat interdiction; repeat the same lane and they learn it. Sell the boat back anytime.',\n    den: 'The house games — dice, numbers, cards, the track. CASH only, entertainment-priced: the house keeps an edge, so play for the thrill, not the rent. Back-room games are against real players.',\n    speakeasy: 'Own the district\\'s nightclub: it farms cash and it\\'s where the city is SEEN. Buy rounds at rivals\\' clubs to build renown; a hot club draws Prohibition raids.',\n    boxing: 'Sign a fighter, train them, stake them against other managers — or the house card. The crowd bets your main events. Your fighters die with your street; your manager legend doesn\\'t.',\n    races: 'Your garage is a stable: tune a car, race the circuit, wager against rivals — or race for pink slips (winner takes the car). NOS is for underdogs.',\n    stable: 'Own the dogs and the ponies: buy, train, race the circuit, breed champions, and run them in the town\\'s daily card where everyone bets.',\n",
